dataTableFormat:
{
  "is multi section": "true",
  "tab groups": [
    {
      "label": "Select a list",
      "sections": [
        {
          "section": "pegl_with_gene",
          "label": "Search PEG lists by gene"
        },
        {
          "section": "all_pegl",
          "label": "All PEG lists"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "all_pegl",
      "header": "All predicted effector gene (PEG) lists",
      "data point": {
        "type": "api",
        "url": "https://hugeampkpncms.org/rest/data?pageid=egl_241",
        "data type": "csv",
        "data wrapper": [
          0,
          "field_data_points"
        ]
      },
      "search parameters": [
        {
          "parameter": "phenotype",
          "label": "Phenotype",
          "type": "list",
          "values": "kp phenotypes"
        }
      ],
      "filter width": "sm",
      "filters": [
        {
          "field": "Effector list name",
          "label": "First author last name",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Trait",
          "label": "Trait",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Phenotype group",
          "label": "Phenotype group",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Reference",
          "label": "Reference title",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Curated vs automated",
          "label": "Curation",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "Top gene vs multiple genes per locus",
          "label": "Genes per locus",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "Scoring system",
          "label": "Scoring system",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "join",
            "field name": "Reference",
            "fields to join": [
              "Title",
              "Citation"
            ],
            "join by": ". "
          },
          {
            "type": "raw",
            "field name": "Effector list name",
            "raw field": "Effector list name"
          },
          {
            "type": "raw",
            "field name": "Trait",
            "raw field": "Trait"
          },
          {
            "type": "raw",
            "field name": "phenotype",
            "raw field": "Trait ID"
          },
          {
            "type": "raw",
            "field name": "Phenotype group",
            "raw field": "Phenotype group"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "PMID"
          },
          {
            "type": "raw",
            "field name": "Effector Gene List",
            "raw field": "Page ID"
          },
          {
            "type": "raw",
            "field name": "List ID",
            "raw field": "Page ID"
          },
          {
            "type": "raw",
            "field name": "Curated vs automated",
            "raw field": "Curated vs automated"
          },
          {
            "type": "raw",
            "field name": "Top gene vs multiple genes per locus",
            "raw field": "Top gene vs multiple genes per locus"
          },
          {
            "type": "raw",
            "field name": "Scoring system",
            "raw field": "Scoring system"
          }
        ],
        "top rows": [
          "Effector list name",
          "Trait",
          "Phenotype group",
          "Reference",
          "PMID",
          "List ID"
        ],
        "column formatting": {
          "List ID": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "View List",
                "parameter": [
                  "id"
                ]
              }
            ]
          },
          "PMID": {
            "type": [
              "link"
            ],
            "link to": "https://pubmed.ncbi.nlm.nih.gov/",
            "new tab": "true"
          }
        },
        "features": [
          "List type"
        ],
        "List type": [
          "Curated vs automated",
          "Top gene vs multiple genes per locus",
          "Scoring system"
        ]
      },
      "pre filters": [
        {
          "field": "phenotype",
          "value": "search parameter",
          "parameter": "phenotype",
          "type": "search"
        }
      ]
    },
    {
      "section id": "pegl_with_gene",
      "header": "Find PEG lists for a gene",
      "data point": {
        "type": "api",
        "url": "https://hugeampkpncms.org/rest/pegl_gene?",
        "parameters": [
          "gene"
        ],
        "parameters type": "parameters",
        "data type": "json",
        "cumulate data": "true",
        "query key name": "Gene"
      },
      "search parameters": [
        {
          "parameter": "gene",
          "label": "Enter gene name",
          "type": "input",
          "values": "kp genes",
          "value number": "multi"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Title",
            "raw field": "title"
          },
          {
            "type": "raw",
            "field name": "List description",
            "raw field": "body"
          },
          {
            "type": "raw",
            "field name": "List ID",
            "raw field": "field_page_id"
          }
        ],
        "top rows": [
          "Title",
          "List description",
          "List ID"
        ],
        "column formatting": {
          "List ID": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "View List",
                "parameter": [
                  "id"
                ]
              }
            ]
          }
        },
        "rows per page": 5
      }
    },
    {
      "section id": "single_pegl",
      "header": "Single PEGL",
      "data point": {
        "type": "api",
        "url": "https://hugeampkpncms.org/rest/directcsv?",
        "parameters": [
          "id"
        ],
        "parameters type": "parameters",
        "data type": "csv",
        "data wrapper": [
          0,
          "field_data_points"
        ]
      },
      "search parameters": [
        {
          "parameter": "id",
          "label": "EGL ID",
          "type": "input",
          "value number": "single",
          "display": "false"
        }
      ],
      "table format": {
        "type": "remote",
        "config wrapper": [
          0,
          "field_data_table_format"
        ]
      },
      "filters": {
        "type": "remote",
        "config wrapper": [
          0,
          "field_filters"
        ]
      },
      "visualizer": {
        "type": "remote",
        "config wrapper": [
          0,
          "field_visualizer_configuration"
        ]
      },
      "section description": {
        "type": "remote",
        "config wrapper": [
          0,
          "body"
        ]
      }
    }
  ]
}
